              "{\"headline\":\"Trump escalates China trade war, threatens tariffs on $200 billion in products\",\"alternativeHeadline\":\"Trump escalates China trade war, threatens tariffs on $200 billion in products\",\"dateModified\":\"2018-06-19T12:27:52.119Z\",\"datePublished\":\"2018-06-19T00:29:42.000Z\",\"author\":[{\"name\":\"David J. Lynch\"},{\"name\":\"Heather Long\"}],\"isPartOf\":{\"name\":\"The Washington Post\",\"description\":\"Breaking news and analysis on politics, business, world, national news, entertainment and more. In-depth DC, Virginia, Maryland news coverage including traffic, weather, crime, education, restaurant reviews and more.\",\"sku\":\"https://subscribe.washingtonpost.com\",\"brand\":{\"name\":\"The Washington Post\"}},\"publisher\":{\"name\":\"The Washington Post\"},\"isAccessibleForFree\":false,\"hasPart\":{\"isAccessibleForFree\":false},\"keywords\":\"business, chinese, trump, general news, government and politics, north america, united states\"}"
